SELECT uint16 = float32 AS c0, toTypeName(uint16 = float32) AS t0, uint16 != float32 AS c1, toTypeName(uint16 != float32) AS t1, uint16 < float32 AS c2, toTypeName(uint16 < float32) AS t2, uint16 <= float32 AS c3, toTypeName(uint16 <= float32) AS t3, uint16 > float32 AS c4, toTypeName(uint16 > float32) AS t4, uint16 >= float32 AS c5, toTypeName(uint16 >= float32) AS t5 FROM he24.numeric ORDER BY row_id
